18	// RandomizedTempPaths allows generating and memoizing random paths, each path being mapped to a specific key.
19	type RandomizedTempPaths struct {
20		root  string
21		paths map[string]string
22		lock  sync.RWMutex
23	}
24	
25	func NewRandomizedTempPaths(root string) *RandomizedTempPaths {
26		return &RandomizedTempPaths{
27			root:  root,
28			paths: map[string]string{},
29		}
30	}
31	
32	func (p *RandomizedTempPaths) Add(key string, value string) {
33		p.lock.Lock()
34		defer p.lock.Unlock()
35		p.paths[key] = value
36	}
37	
38	// GetPath generates a path for the given key or returns previously generated one.
39	func (p *RandomizedTempPaths) GetPath(key string) (string, error) {
40		p.lock.Lock()
41		defer p.lock.Unlock()
42		if val, ok := p.paths[key]; ok {
43			return val, nil
44		}
45		uniqueId, err := uuid.NewRandom()
46		if err != nil {
47			return "", err
48		}
49		repoPath := filepath.Join(p.root, uniqueId.String())
50		p.paths[key] = repoPath
51		return repoPath, nil
52	}
53	
54	// GetPathIfExists gets a path for the given key if it exists. Otherwise, returns an empty string.
55	func (p *RandomizedTempPaths) GetPathIfExists(key string) string {
56		p.lock.RLock()
57		defer p.lock.RUnlock()
58		if val, ok := p.paths[key]; ok {
59			return val
60		}
61		return ""
62	}
63	
64	// GetPaths gets a copy of the map of paths.
65	func (p *RandomizedTempPaths) GetPaths() map[string]string {
66		p.lock.RLock()
67		defer p.lock.RUnlock()
68		paths := map[string]string{}
69		maps.Copy(paths, p.paths)
70		return paths
71	}
