539	// resolveReferencedSources resolves the revisions for the given referenced sources. This lets us invalidate the cached
540	// when one or more referenced sources change.
541	//
542	// Much of this logic is duplicated in runManifestGenAsync. If making changes here, check whether runManifestGenAsync
543	// should be updated.
544	func resolveReferencedSources(hasMultipleSources bool, source *v1alpha1.ApplicationSourceHelm, refSources map[string]*v1alpha1.RefTarget, newClientResolveRevision gitClientGetter, gitClientOpts git.ClientOpts) (map[string]string, error) {
545		repoRefs := make(map[string]string)
546		if !hasMultipleSources || source == nil {
547			return repoRefs, nil
548		}
549	
550		refFileParams := make([]string, 0)
551		for _, fileParam := range source.FileParameters {
552			refFileParams = append(refFileParams, fileParam.Path)
553		}
554		refCandidates := append(source.ValueFiles, refFileParams...)
555	
556		for _, valueFile := range refCandidates {
557			if !strings.HasPrefix(valueFile, "$") {
558				continue
559			}
560			refVar := strings.Split(valueFile, "/")[0]
561	
562			refSourceMapping, ok := refSources[refVar]
563			if !ok {
564				if len(refSources) == 0 {
565					return nil, fmt.Errorf("source referenced %q, but no source has a 'ref' field defined", refVar)
566				}
567				refKeys := make([]string, 0)
568				for refKey := range refSources {
569					refKeys = append(refKeys, refKey)
570				}
571				return nil, fmt.Errorf("source referenced %q, which is not one of the available sources (%s)", refVar, strings.Join(refKeys, ", "))
572			}
573			if refSourceMapping.Chart != "" {
574				return nil, errors.New("source has a 'chart' field defined, but Helm charts are not yet not supported for 'ref' sources")
575			}
576			normalizedRepoURL := git.NormalizeGitURL(refSourceMapping.Repo.Repo)
577			_, ok = repoRefs[normalizedRepoURL]
578			if !ok {
579				_, referencedCommitSHA, err := newClientResolveRevision(&refSourceMapping.Repo, refSourceMapping.TargetRevision, gitClientOpts)
580				if err != nil {
581					log.Errorf("Failed to get git client for repo %s: %v", refSourceMapping.Repo.Repo, err)
582					return nil, fmt.Errorf("failed to get git client for repo %s", refSourceMapping.Repo.Repo)
583				}
584	
585				repoRefs[normalizedRepoURL] = referencedCommitSHA
586			}
587		}
588		return repoRefs, nil
589	}
