591	func (s *Service) GenerateManifest(ctx context.Context, q *apiclient.ManifestRequest) (*apiclient.ManifestResponse, error) {
592		var res *apiclient.ManifestResponse
593		var err error
594	
595		// Skip this path for ref only sources
596		if q.HasMultipleSources && q.ApplicationSource.Path == "" && !q.ApplicationSource.IsOCI() && !q.ApplicationSource.IsHelm() && q.ApplicationSource.IsRef() {
597			log.Debugf("Skipping manifest generation for ref only source for application: %s and ref %s", q.AppName, q.ApplicationSource.Ref)
598			_, revision, err := s.newClientResolveRevision(q.Repo, q.Revision, git.WithCache(s.cache, !q.NoRevisionCache && !q.NoCache))
599			res = &apiclient.ManifestResponse{
600				Revision: revision,
601			}
602			return res, err
603		}
604	
605		cacheFn := func(cacheKey string, refSourceCommitSHAs cache.ResolvedRevisions, firstInvocation bool) (bool, error) {
606			ok, resp, err := s.getManifestCacheEntry(cacheKey, q, refSourceCommitSHAs, firstInvocation)
607			res = resp
608			return ok, err
609		}
610	
611		tarConcluded := false
612		var promise *ManifestResponsePromise
613	
614		operation := func(repoRoot, commitSHA, cacheKey string, ctxSrc operationContextSrc) error {
615			// do not generate manifests if Path and Chart fields are not set for a source in Multiple Sources
616			if q.HasMultipleSources && q.ApplicationSource.Path == "" && q.ApplicationSource.Chart == "" {
617				log.WithFields(map[string]any{
618					"source": q.ApplicationSource,
619				}).Debugf("not generating manifests as path and chart fields are empty")
620				res = &apiclient.ManifestResponse{
621					Revision: commitSHA,
622				}
623				return nil
624			}
625	
626			promise = s.runManifestGen(ctx, repoRoot, commitSHA, cacheKey, ctxSrc, q)
627			// The fist channel to send the message will resume this operation.
628			// The main purpose for using channels here is to be able to unlock
629			// the repository as soon as the lock in not required anymore. In
630			// case of CMP the repo is compressed (tgz) and sent to the cmp-server
631			// for manifest generation.
632			select {
633			case err := <-promise.errCh:
634				return err
635			case resp := <-promise.responseCh:
636				res = resp
637			case tarDone := <-promise.tarDoneCh:
638				tarConcluded = tarDone
639			}
640			return nil
641		}
642	
643		settings := operationSettings{sem: s.parallelismLimitSemaphore, noCache: q.NoCache, noRevisionCache: q.NoRevisionCache, allowConcurrent: q.ApplicationSource.AllowsConcurrentProcessing()}
644		err = s.runRepoOperation(ctx, q.Revision, q.Repo, q.ApplicationSource, q.VerifySignature, cacheFn, operation, settings, q.HasMultipleSources, q.RefSources)
645	
646		// if the tarDoneCh message is sent it means that the manifest
647		// generation is being managed by the cmp-server. In this case
648		// we have to wait for the responseCh to send the manifest
649		// response.
650		if tarConcluded && res == nil {
651			select {
652			case resp := <-promise.responseCh:
653				res = resp
654			case err := <-promise.errCh:
655				return nil, err
656			}
657		}
658		return res, err

