161	func (s *Service) Init() error {
162		_, err := os.Stat(s.rootDir)
163		if os.IsNotExist(err) {
164			return os.MkdirAll(s.rootDir, 0o300)
165		}
166		if err == nil {
167			// give itself read permissions to list previously written directories
168			err = os.Chmod(s.rootDir, 0o700)
169		}
170		var dirEntries []fs.DirEntry
171		if err == nil {
172			dirEntries, err = os.ReadDir(s.rootDir)
173		}
174		if err != nil {
175			log.Warnf("Failed to restore cloned repositories paths: %v", err)
176			return nil
177		}
178	
179		for _, file := range dirEntries {
180			if !file.IsDir() {
181				continue
182			}
183			fullPath := filepath.Join(s.rootDir, file.Name())
184			closer := s.gitRepoInitializer(fullPath)
185			if repo, err := gogit.PlainOpen(fullPath); err == nil {
186				if remotes, err := repo.Remotes(); err == nil && len(remotes) > 0 && len(remotes[0].Config().URLs) > 0 {
187					s.gitRepoPaths.Add(git.NormalizeGitURL(remotes[0].Config().URLs[0]), fullPath)
188				}
189			}
190			utilio.Close(closer)
191		}
192		// remove read permissions since no-one should be able to list the directories
193		return os.Chmod(s.rootDir, 0o300)
194	}
