2697		revisionPresent := true
2698		for _, revision := range targetRevisions {
2699			revisionPresent = gitClient.IsRevisionPresent(revision)
2700			if !revisionPresent {
2701				break
2702			}
2703		}
2704		// Fetching can be skipped if the revision is already present locally.
2705		if revisionPresent {
2706			return nil
2707		}
2708		// Fetching with no revision first. Fetching with an explicit version can cause repo bloat. https://github.com/argoproj/argo-cd/issues/8845
