2710		if err != nil {
2711			return err
2712		}
2713		for _, revision := range targetRevisions {
2714			if !gitClient.IsRevisionPresent(revision) {
2715				// When fetching with no revision, only refs/heads/* and refs/remotes/origin/* are fetched. If fetch fails
